query:
-- Measure for Measure
DELETE FROM projectTags WHERE projectId = (SELECT id FROM projects WHERE slug = 'measure-for-measure');
INSERT INTO projectTags (projectId, tagId)
SELECT p.id, t.id FROM projects p CROSS JOIN tags t
WHERE p.slug = 'measure-for-measure'
AND t.name IN ('Shakespeare', 'Minimalist', 'Unit Set', 'Theatre Festival', '2021');

-- Macbeth
DELETE FROM projectTags WHERE projectId = (SELECT id FROM projects WHERE slug = 'macbeth');
