SELECT p.id, t.id FROM projects p CROSS JOIN tags t
WHERE p.slug = 'macbeth'
AND t.name IN ('Shakespeare', 'Gothic', 'Minimalist', 'Theatre Festival', '2021', 'Tragedy');

