WHERE p.slug = 'midsummer-nights-dream'
AND t.name IN ('Shakespeare', 'Romantic', 'Unit Set', 'Theatre Festival', '2020', 'Comedy');

-- Othello
DELETE FROM projectTags WHERE projectId = (SELECT id FROM projects WHERE slug = 'othello');
